CREATE ROLE lehrkraft;
GRANT SELECT ON schueler
  TO lehrkraft;

CREATE ROLE huber LOGIN
  PASSWORD 'Geheim!23';
GRANT lehrkraft TO huber;

-- als huber:
SELECT name FROM schueler;
-- Anna, Ben
UPDATE schueler SET name = 'X'
  WHERE sch_nr = 1;
-- ERROR:  permission denied
--   for table schueler

REVOKE SELECT ON schueler
  FROM lehrkraft;
-- huber: permission denied

-- nur bestimmte Spalten:
GRANT SELECT (sch_nr, name)
  ON schueler TO lehrkraft;
SELECT name FROM schueler; -- ok
SELECT svnr FROM schueler;
-- ERROR:  permission denied
--   for table schueler

CREATE VIEW schueler_4ahif AS
  SELECT sch_nr, name
  FROM schueler
  WHERE klasse = '4AHIF';

CREATE ROLE kv_4ahif;
GRANT SELECT ON schueler_4ahif
  TO kv_4ahif;
GRANT kv_4ahif TO maier;

-- als maier:
SELECT * FROM schueler_4ahif;
-- 1 | Anna
SELECT * FROM schueler;
-- ERROR:  permission denied
